function c(t){if(!t)return"";const r=typeof t=="number"?t:new Date(t).getTime(),e=Date.now()-r,a=6e4,i=36e5,o=864e5;if(e<a)return"刚刚";if(e<i)return`${Math.floor(e/a)} 分钟前`;if(e<o)return`${Math.floor(e/i)} 小时前`;if(e<30*o)return`${Math.floor(e/o)} 天前`;const n=new Date(r);return`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,"0")}-${String(n.getDate()).padStart(2,"0")}`}function f(t){return t>=1e4?(t/1e4).toFixed(1).replace(/\.0$/,"")+"w":t>=1e3?(t/1e3).toFixed(1).replace(/\.0$/,"")+"k":String(t)}function u(t){const r=Number(t)||0;return r>=1024*1024?(r/1024/1024).toFixed(1)+" MB":Math.ceil(r/1024)+" KB"}export{u as a,f as c,c as t};
